import * as THREE from "three";
import { getDefaultThreeConfig } from "../../../config/base.config.js";
import { ABOUT_LIGHT_STATE_DEFAULTS } from "../../../config/scene-light.config.js";
import {
  aboutBackground,
  aboutLights,
  earth,
} from "../../../core/setup.js";
import type { PageThreeConfig } from "../../../types/core.types.js";
import type {
  ContactInitialState,
  ContactPageConfig,
  ContactSceneState,
} from "../../../types/contact.types.js";

const defaultThree = getDefaultThreeConfig();

export const CONTACT_DEFAULT_SCENE_STATE: ContactSceneState = {
  camera: {
    position: { x: -10, y: 4, z: 42 },
    target: { x: 10, y: 2, z: -8 },
    fov: 52,
  },
  light: {
    ...ABOUT_LIGHT_STATE_DEFAULTS,
    rig: {
      position: { x: 0, y: 0, z: 0 },
      rotation: { x: 0, y: 0, z: 0 },
      scale: { x: 1, y: 1, z: 1 },
      visible: true,
    },
    intensity: 1,
    ambientLight: 0.42,
    keyLight: 3,
    fillLight: 0.78,
    rimLight: 0.32,
  },
  earth: {
    position: { x: 14, y: 2, z: -24 },
    rotation: { x: 0, y: 18, z: 0 },
    scale: { x: 1.16, y: 1.16, z: 1.16 },
    visible: true,
  },
};

function createContactInitialState(
  sceneState: ContactSceneState,
): ContactInitialState {
  return {
    camera: {
      position: { ...sceneState.camera.position },
      fov: sceneState.camera.fov,
    },
    cameraTarget: {
      position: { ...sceneState.camera.target },
    },
    aboutLights: {
      ...sceneState.light,
      rig: {
        position: { ...sceneState.light.rig.position },
        rotation: { ...sceneState.light.rig.rotation },
        scale: { ...sceneState.light.rig.scale },
        visible: sceneState.light.rig.visible,
      },
    },
    earth: {
      position: { ...sceneState.earth.position },
      rotation: { ...sceneState.earth.rotation },
      scale: { ...sceneState.earth.scale },
      visible: sceneState.earth.visible,
    },
  };
}

export const contactThree: PageThreeConfig = {
  ...defaultThree,
  scene: { ...defaultThree.scene, fog: null },
  camera: {
    ...defaultThree.camera,
    position: { ...CONTACT_DEFAULT_SCENE_STATE.camera.position },
    fov: CONTACT_DEFAULT_SCENE_STATE.camera.fov,
  },
  cameraTarget: {
    position: { ...CONTACT_DEFAULT_SCENE_STATE.camera.target },
  },
  shadowMap: {
    enabled: true,
    type: THREE.PCFSoftShadowMap,
  },
};

export const contactConfig: ContactPageConfig = {
  pageId: "contact",
  three: contactThree,
  initialState: createContactInitialState(CONTACT_DEFAULT_SCENE_STATE),
  scenes: {
    contact: {},
